#!/usr/bin/env node
import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import process from "node:process";
import { chromium } from "playwright";

function arg(name, fallback) {
  const index = process.argv.indexOf(`--${name}`);
  return index >= 0 ? process.argv[index + 1] : fallback;
}
const start = arg("start");
const out = path.resolve(arg("out", "./rendered-site"));
const maxPages = Number(arg("maxPages", "80"));
const pathPrefix = arg("pathPrefix", "/");
if (!start) throw new Error("--start is required");

const startUrl = new URL(start);
const queue = [startUrl.href];
const seen = new Set();
const records = [];

function localFile(url) {
  const u = new URL(url);
  let p = decodeURIComponent(u.pathname);
  if (p.endsWith("/")) p += "index";
  if (!path.extname(p)) p += ".html";
  p = p.replace(/^\/+/, "").replace(/[<>:"|?*]/g, "_");
  return path.join(out, p);
}

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  locale: "zh-CN"
});
const page = await context.newPage();

while (queue.length && seen.size < maxPages) {
  const current = queue.shift();
  if (seen.has(current)) continue;
  seen.add(current);
  try {
    const response = await page.goto(current, { waitUntil: "domcontentloaded", timeout: 60000 });
    await page.waitForTimeout(1200);
    const html = await page.content();
    const file = localFile(current);
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, html, "utf8");
    const sha256 = crypto.createHash("sha256").update(html).digest("hex");
    records.push({ url: current, file: path.relative(out, file), status: response?.status() ?? null, sha256 });

    const hrefs = await page.locator("a[href]").evaluateAll(nodes =>
      nodes.map(n => n.getAttribute("href")).filter(Boolean)
    );
    for (const href of hrefs) {
      try {
        const u = new URL(href, current);
        u.hash = "";
        if (u.origin !== startUrl.origin) continue;
        if (!u.pathname.startsWith(pathPrefix)) continue;
        if (/\.(png|jpe?g|gif|svg|webp|zip|gz|pdf|mp4|mp3)$/i.test(u.pathname)) continue;
        if (!seen.has(u.href)) queue.push(u.href);
      } catch {}
    }
  } catch (error) {
    records.push({ url: current, error: String(error) });
  }
}
await context.close();
await browser.close();
await fs.mkdir(out, { recursive: true });
await fs.writeFile(path.join(out, "crawl-manifest.json"), JSON.stringify(records, null, 2));
console.log(`Saved ${records.filter(r => r.file).length} pages to ${out}`);

﻿param(
  [ValidateSet("Core", "Full")]
  [string]$Mode = "Core",
  [switch]$FetchRenderedSites,
  [string]$OutputRoot = ""
)

$ErrorActionPreference = "Stop"
$ScriptRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$PackRoot = Split-Path -Parent $ScriptRoot
if ([string]::IsNullOrWhiteSpace($OutputRoot)) {
  $OutputRoot = Join-Path $PackRoot "downloaded_official_docs"
}
New-Item -ItemType Directory -Force -Path $OutputRoot | Out-Null

$components = Get-Content (Join-Path $PackRoot "config\components.json") -Raw |
  ConvertFrom-Json

$coreIds = @(
  "deepseek", "mimo", "coze", "midscene", "playwright", "json-schema",
  "ajv", "openapi", "nodejs", "typescript", "eslint", "ffmpeg",
  "fineract", "mifos"
)

function Invoke-Retry {
  param([scriptblock]$Action, [int]$Attempts = 3)
  for ($i = 1; $i -le $Attempts; $i++) {
    try { & $Action; return }
    catch {
      if ($i -eq $Attempts) { throw }
      Start-Sleep -Seconds ([Math]::Min(10, 2 * $i))
    }
  }
}

function Safe-Name([string]$Value) {
  return ($Value -replace '[\\/:*?"<>| ]+', '_')
}

function Save-Link([string]$Dir, [string]$Name, [string]$Url) {
  New-Item -ItemType Directory -Force -Path $Dir | Out-Null
  "[InternetShortcut]`r`nURL=$Url`r`n" |
    Set-Content -Encoding UTF8 (Join-Path $Dir "$Name.url")
}

foreach ($c in $components) {
  if ($Mode -eq "Core" -and $coreIds -notcontains $c.id) { continue }

  $categoryDir = Join-Path $OutputRoot (Safe-Name $c.category)
  $componentDir = Join-Path $categoryDir (Safe-Name $c.name)
  New-Item -ItemType Directory -Force -Path $componentDir | Out-Null

$meta = [ordered]@{
    id = $c.id
    name = $c.name
    category = $c.category
    priority = $c.priority
    role = $c.role
    downloadedAt = (Get-Date).ToString("o")
  }
  $meta | ConvertTo-Json -Depth 8 |
    Set-Content -Encoding UTF8 (Join-Path $componentDir "component-metadata.json")

  $i = 0
  foreach ($url in $c.docs) {
    $i++
    Save-Link $componentDir ("docs_{0:D2}" -f $i) $url

    if ($FetchRenderedSites) {
      $siteOut = Join-Path $componentDir ("rendered_site_{0:D2}" -f $i)
      if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
        Write-Warning "Node.js not found; skip rendered site: $url"
      } else {
        $toolDir = Join-Path $OutputRoot "_crawler_tool"
        New-Item -ItemType Directory -Force -Path $toolDir | Out-Null
        if (-not (Test-Path (Join-Path $toolDir "node_modules\playwright"))) {
          Push-Location $toolDir
          if (-not (Test-Path "package.json")) { npm init -y | Out-Null }
          npm install playwright | Out-Host
          npx playwright install chromium | Out-Host
          Pop-Location
        }
        $env:NODE_PATH = Join-Path $toolDir "node_modules"
        node (Join-Path $ScriptRoot "rendered_docs_crawler.mjs") `
          --start $url --out $siteOut --maxPages 80 --pathPrefix "/"
      }
    }
  }

foreach ($repo in $c.repos) {
    if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
      Write-Warning "git not found; only URL shortcut saved: $repo"
      Save-Link $componentDir ("repo_" + (Safe-Name $repo)) $repo
      continue
    }
    $repoName = ($repo.TrimEnd("/") -split "/")[-1]
    $dest = Join-Path $componentDir ("repo_" + (Safe-Name $repoName))
    if (Test-Path $dest) {
      Write-Host "Repository exists, skip: $dest"
      continue
    }
    Write-Host "Cloning $repo"
    Invoke-Retry { git clone --depth 1 $repo $dest }
    if (Test-Path (Join-Path $dest ".git")) {
      Remove-Item -Force -Recurse (Join-Path $dest ".git")
    }
  }

  foreach ($pkg in $c.npm) {
    if (-not (Get-Command npm -ErrorAction SilentlyContinue)) {
      Write-Warning "npm not found; skip npm pack: $pkg"
      continue
    }
    $npmDir = Join-Path $componentDir "npm_packages"
    New-Item -ItemType Directory -Force -Path $npmDir | Out-Null
    Push-Location $npmDir
    Write-Host "Packing npm package $pkg"
    Invoke-Retry { npm pack $pkg | Out-Host }
    Pop-Location
  }

  foreach ($pdf in $c.pdfs) {
    if (-not (Get-Command curl.exe -ErrorAction SilentlyContinue)) {
      Write-Warning "curl.exe not found; skip PDF: $pdf"
      continue
    }
    $pdfName = (Safe-Name (($pdf -split "/")[-1])) + ".pdf"
    $target = Join-Path $componentDir $pdfName
    if (-not (Test-Path $target)) {
      Invoke-Retry { curl.exe -L --fail --retry 2 -o $target $pdf }
    }
  }
}

python (Join-Path $ScriptRoot "verify_manifest.py") $OutputRoot

$zip = "$OutputRoot.zip"
if (Test-Path $zip) { Remove-Item $zip -Force }
Compress-Archive -Path (Join-Path $OutputRoot "*") -DestinationPath $zip -CompressionLevel Optimal
Write-Host "Completed: $zip"
